def can_chain(dominoes):
    """Return a closed chain of the given dominoes, or None if impossible.

    A valid chain uses every domino exactly once (reversing a domino is
    allowed), has matching halves between adjacent dominoes, and the
    unpaired ends (first and last) match each other.
    """
    if not dominoes:
        return []

    n = len(dominoes)
    used = [False] * n

    def search(chain, current):
        if len(chain) == n:
            return chain if chain[-1][1] == chain[0][0] else None
        for j in range(n):
            if used[j]:
                continue
            a, b = dominoes[j]
            if a == current:
                used[j] = True
                result = search(chain + [(a, b)], b)
                used[j] = False
                if result is not None:
                    return result
            elif b == current:
                used[j] = True
                result = search(chain + [(b, a)], a)
                used[j] = False
                if result is not None:
                    return result
        return None

    # Try each domino (in both orientations) as the start of the chain.
    for i in range(n):
        for first in (dominoes[i], (dominoes[i][1], dominoes[i][0])):
            used[i] = True
            result = search([first], first[1])
            used[i] = False
            if result is not None:
                return result

    return None
